# 脱敏：把文本中所有的 x 替换成 *。


def mask(text):
    return text.replace("x", "*", 1)

verification_tests:
from target import mask


def test_no_match():
    assert mask("a") == "a"


def test_single_match():
    assert mask("x") == "*"


def test_multiple_matches():
    assert mask("axbx") == "a*b*"
